import { expect, test, uniqueName } from "../../fixtures";

test.describe("manage vendors", () => {
  test("create a vendor", { tag: "@VEN-01" }, async ({ apiAs }) => {
    // Arrange
    const member = await apiAs("member");
    const name = uniqueName("Acme Freight");

    // Act
    const response = await member.post("/api/vendors", {
      data: { name, category: "logistics", contact_email: "ops@acmefreight.example" },
    });

    // Assert
    expect(response.status(), await response.text()).toBe(201);
    const vendor = await response.json();
    expect(vendor.name).toBe(name);
    expect(vendor.status).toBe("draft");

    const trail = await member.get(`/api/vendors/${vendor.id}/audit`);
    expect(trail.status(), await trail.text()).toBe(200);
    const actions = ((await trail.json()) as { items: { action: string }[] }).items.map(
      (event) => event.action,
    );
    expect(actions, "audit trail actions").toContain("vendor.created");
  });
});
